namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    [Fact]
    public void WhenGoldMemberSpendsTenThousandCents_ShouldPayNineThousandFiveHundred()
    {
        Assert.Equal(9_500, GoldMemberPays(subtotalCents: 10_000));
    }

    [Fact]
    public void WhenGoldMemberSpendsTwentyThousandCents_ShouldPayNineteenThousand()
    {
        Assert.Equal(19_000, GoldMemberPays(subtotalCents: 20_000));
    }

    [Fact]
    public void WhenGoldMemberSpendsFiveThousandCents_ShouldPayFourThousandSevenHundredFifty()
    {
        Assert.Equal(4_750, GoldMemberPays(subtotalCents: 5_000));
    }

    [Fact]
    public void WhenGoldMemberSpendsNothing_ShouldPayNothing()
    {
        Assert.Equal(0, GoldMemberPays(subtotalCents: 0));
    }

    private static int GoldMemberPays(int subtotalCents)
    {
        var useCase = new CalculatePayableTotal(new LoyaltyDiscountPolicy());
        return useCase.For(subtotalCents, LoyaltyTier.Gold);
    }
}
